package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.tencent.weknora.security.AuthFilter;
import com.tencent.weknora.storage.StorageResolver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.config.AutowireCapableBeanFactory;
import org.springframework.http.HttpMethod;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;

/** Actual public admission/authentication, low queue and physical deletion with Hikari pool one. */
@org.springframework.boot.test.context.SpringBootTest(properties={"weknora.jwt-secret=isolated-native-pipeline-trace-secret","weknora.bridge.enabled=false","weknora.knowledge.processing.enabled=true","weknora.knowledge.upload.enabled=true","weknora.tasks.enabled=true","weknora.tasks.poll-millis=3600000","weknora.retrieve-driver=sqlite","SSRF_WHITELIST=127.0.0.1","SSRF_DNS_WHITELIST_ONLY=true","NEO4J_ENABLE=false","logging.level.root=WARN","debug=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class KnowledgeDeletePipelineHttpIntegrationTest {
 @org.springframework.test.context.DynamicPropertySource static void properties(org.springframework.test.context.DynamicPropertyRegistry p){IndexDeletePipelineHttpIntegrationTest.properties(p);}
 @Autowired AutowireCapableBeanFactory beans;@Autowired KnowledgeListDeleteHandler cleanup;@Autowired StorageResolver storage;
 final IndexDeletePipelineHttpIntegrationTest f=new IndexDeletePipelineHttpIntegrationTest();final ObjectMapper json=new ObjectMapper();final List<String> keys=new ArrayList<>();
 @BeforeEach void setup()throws Exception{beans.autowireBean(f);f.setup();f.f.jdbc.update("UPDATE knowledges SET deleted_at='2026-01-01T00:00:00Z' WHERE tenant_id=8 AND knowledge_base_id='trace-kb' AND deleted_at IS NULL");f.f.jdbc.update("UPDATE tenant_members SET role='admin' WHERE user_id IN ('owner','caller')");f.f.jdbc.update("UPDATE kb_shares SET permission='editor',deleted_at=NULL WHERE id='trace-share'");f.f.jdbc.update("UPDATE organization_tenant_members SET role='editor' WHERE id='trace-target'");}
 @AfterEach void release(){for(String key:keys)f.f.jdbc.update("DELETE FROM tenant_api_keys WHERE key_hash=?",AuthFilter.hashApiKey(key));f.f.jdbc.update("UPDATE tenant_members SET role='admin' WHERE user_id IN ('owner','caller')");f.f.jdbc.update("UPDATE kb_shares SET permission='editor',deleted_at=NULL WHERE id='trace-share'");f.release();}
 JsonNode request(String method,String path,String body,String credential,boolean machine,int status)throws Exception{var builder=MockMvcRequestBuilders.request(HttpMethod.valueOf(method),path).contentType("application/json").content(body);builder.header(machine?"X-API-Key":"Authorization",machine?credential:"Bearer "+credential);var response=f.f.mvc.perform(builder).andReturn().getResponse();assertEquals(status,response.getStatus(),response.getContentAsString());return json.readTree(response.getContentAsByteArray());}
 String key(String cap,boolean full){String value="delete-key-"+UUID.randomUUID();keys.add(value);f.f.jdbc.update("INSERT INTO tenant_api_keys(tenant_id,name,key_hash,api_key,full_access,capabilities,knowledge_base_ids) VALUES(8,'Delete operator',?,?,?,?,?)",AuthFilter.hashApiKey(value),value,full,"[\""+cap+"\"]","[\"trace-kb\"]");return value;}
 @Test void ownCreatorViewerSingleDeleteRemovesPersistedBytesAndIndexes()throws Exception{String doc=f.prepared();f.f.jdbc.update("UPDATE tenant_members SET role='viewer' WHERE user_id='owner' AND tenant_id=8");var result=request("DELETE","/api/v1/knowledge/"+doc,"",f.f.token("owner",8),false,200);finish(List.of(doc),"owner",result.path("data").path("task_id").asText());}
 @Test void sharedBatchRetainsOrderedDedupeAndOriginalActor()throws Exception{String first=f.prepared(),second=f.prepared();var result=request("POST","/api/v1/knowledge/batch-delete",json.writeValueAsString(Map.of("kb_id","trace-kb","ids",List.of(" "+second+" ",first,second))),f.f.callerToken,false,200);assertEquals(2,result.path("data").path("deleted_count").asInt());finish(List.of(second,first),"caller",result.path("data").path("task_id").asText());}
 @Test void onlyOwnerAdminOrFullApiKeyCanClearWhileEmptyKbDoesNotEnqueue()throws Exception{String doc=f.prepared();request("DELETE","/api/v1/knowledge-bases/trace-kb/knowledge","",f.f.callerToken,false,403);request("DELETE","/api/v1/knowledge-bases/trace-kb/knowledge","",key("ingest",false),true,403);String full=key("ingest",true);var result=request("DELETE","/api/v1/knowledge-bases/trace-kb/knowledge","",full,true,200);assertFalse(result.path("data").has("task_id"));assertEquals(1,result.path("data").path("deleted_count").asInt());finish(List.of(doc),"owner",null);long tasks=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs WHERE type='knowledge:list_delete'",Long.class);var empty=request("DELETE","/api/v1/knowledge-bases/trace-kb/knowledge","",full,true,200);assertEquals("Knowledge base is already empty",empty.path("message").asText());assertEquals(0,empty.path("data").path("deleted_count").asInt());assertEquals(tasks,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs WHERE type='knowledge:list_delete'",Long.class));}
 void finish(List<String> ids,String actor,String publicTask)throws Exception{
  int calls=f.calls.get();long before=f.f.jdbc.queryForObject("SELECT storage_used FROM tenants WHERE id=8",Long.class),size=0;var references=new ArrayList<String>();var store=storage.forKnowledgeBase(8,"trace-kb").files();
  for(String id:ids){size+=f.f.jdbc.queryForObject("SELECT storage_size FROM knowledges WHERE id=?",Long.class,id);references.add(f.f.jdbc.queryForObject("SELECT file_path FROM knowledges WHERE id=?",String.class,id));assertTrue(f.f.count("lite_embeddings",id)>0);assertEquals("completed",f.f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,id));}
  for(String ref:references)try(var in=store.open(ref)){assertTrue(in.readAllBytes().length>0);}
  var job=f.f.claim("low");assertEquals("knowledge:list_delete",job.type());assertEquals(8,job.tenantId());assertEquals(4,job.maxAttempts());assertEquals(7200000,job.timeoutMillis());assertEquals(json.valueToTree(ids),job.payload().path("knowledge_ids"));assertEquals(actor,job.payload().path("initiator").path("user_id").asText());if(publicTask!=null)assertEquals(publicTask,job.id());
  assertEquals(ids.size(),cleanup.execute(job,f.f.cancellation(job)).path("deleted").asInt());assertTrue(f.f.tasks.complete(job,json.createObjectNode()));for(String id:ids){assertEquals(0,f.f.count("lite_embeddings",id));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND deleted_at IS NULL",Integer.class,id));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM knowledges WHERE id=? AND deleted_at IS NOT NULL",Integer.class,id));}for(String ref:references)assertThrows(java.io.IOException.class,()->{try(var in=store.open(ref)){in.readAllBytes();}});assertEquals(calls,f.calls.get());assertEquals(Math.max(0,before-size),f.f.jdbc.queryForObject("SELECT storage_used FROM tenants WHERE id=8",Long.class));
  var audit=f.f.jdbc.queryForMap("SELECT tenant_id,actor_user_id,details FROM audit_logs WHERE action='knowledge.batch_deleted' AND scope_id='trace-kb' ORDER BY id DESC LIMIT 1");assertEquals(actor,audit.get("actor_user_id"));assertEquals(8L,((Number)audit.get("tenant_id")).longValue());assertEquals(job.id(),json.readTree(audit.get("details").toString()).path("task_id").asText());
 }
}
